style.css:
@-moz-document url-prefix("https://www.roblox.com/") {
ul.nav:nth-child(2) > li:nth-child(2) > a:nth-child(1),ul.nav:nth-child(2) > li:nth-child(1) > a:nth-child(2) {
        font-size: 0;
        visibility: hidden;
        padding: 0;
        margin-top: 6px;
    }

    ul.nav:nth-child(2) > li:nth-child(2) > a:nth-child(1)::after {
        content:"Catalog";
        font-size: 16px;
        visibility: visible;
        padding: 8px 9px;
        border-radius: 5px;
    }
    
    ul.nav:nth-child(2) > li:nth-child(1) > a:nth-child(2)::after {
        content:"Games";
        font-size: 16px;
        visibility: visible;
        padding: 8px 9px;
        border-radius: 5px;
    }
}

@-moz-document url-prefix("https://www.roblox.com/home") {
.wide-game-tile-list {
        display: none;
    }
    
    #HomeContainer > div.place-list-container > div > div > div:nth-child(2) > div.game-sort-header-container {
        display: none;
    }
    
    div[data-testid="home-page-game-grid"] {
        display: none;
    }
    
    #HomeContainer > div.place-list-container > div > div > div.col-xs-12.container-list.places-list {
        display: none;
    }
}

@-moz-document url-prefix("https://www.roblox.com/catalog") {
#catalog-content > div.catalog-header > div.catalog-heading-container > div.topic-container {
        display: none;
    }
}
